size_t group_index = min_bit / binfo->group_size;
size_t group_offset = min_bit % binfo->group_size;
while (group_index < binfo->ngroups) {
    if (binfo->group_mask == 0) {
        group_index++;
        group_offset = 0;
        continue;
    }
    std::size_t bit_index = group_index * binfo->group_size + group_offset;
    while (group_offset < binfo->group_size) {
        if (!(bitmap[group_index] & (1ULL << group_offset))) {
            return bit_index;
        }
        group_offset++;
        bit_index++;
    }
    group_index++;
    group_offset = 0;
}
return binfo->nbits;

